package org.apache.rocketmq.acl.common;

import org.junit.Assert;
import org.junit.Test;
import java.util.Properties;

public class SessionCredentialsTest {

    @Test
    public void equalsTest() {
        // Create two session credentials instances with identical properties
        SessionCredentials sessionCredential1 = new SessionCredentials("RocketMQ", "12345678");
        sessionCredential1.setSecurityToken("abcd");

        SessionCredentials sessionCredential2 = new SessionCredentials("RocketMQ", "12345678", "abcd");

        // Update the content of both instances
        Properties properties = new Properties();
        properties.setProperty(SessionCredentials.ACCESS_KEY, "RocketMQ");
        properties.setProperty(SessionCredentials.SECRET_KEY, "12345678");
        properties.setProperty(SessionCredentials.SIGNATURE, "initialSignature");

        sessionCredential1.updateContent(properties);
        sessionCredential2.updateContent(properties);

        // Check if the instances are equal
        Assert.assertTrue("Instances should be equal initially", sessionCredential1.equals(sessionCredential2));

        // Change sessionCredential2's secret key and signature
        sessionCredential2.setSecretKey("87654321");
        sessionCredential2.setSignature("changedSignature");

        // Check if instances are no longer equal
        Assert.assertFalse("Instances should not be equal after changes", sessionCredential1.equals(sessionCredential2));
    }
}

