        // UPDATE_AND_CREATE_TOPIC
<COVER>        ADMIN_CODE.add(RequestCode.UPDATE_AND_CREATE_TOPIC);
        // UPDATE_BROKER_CONFIG
<COVER>        ADMIN_CODE.add(RequestCode.UPDATE_BROKER_CONFIG);
