        Assert.assertEquals(NORMAL_TOPIC, emptyNamespaceResult);

        // Empty resource should return empty
        String emptyResourceResult = NamespaceUtil.wrapNamespace(NAMESPACE, "");
        Assert.assertEquals("", emptyResourceResult);
    }

