    public static boolean isAlreadyWithNamespace(String resource, String namespace) {
<COVER>        if (StringUtils.isEmpty(namespace) || StringUtils.isEmpty(resource) || isSystemResource(resource)) {
            return false;
        }

<COVER>        String resourceWithoutRetryAndDLQ = withOutRetryAndDLQ(resource);

<COVER>        return resourceWithoutRetryAndDLQ.startsWith(namespace + NAMESPACE_SEPARATOR);
    }

    public static String wrapNamespaceAndRetry(String namespace, String consumerGroup) {
        if (StringUtils.isEmpty(consumerGroup)) {
